from django import forms
class PredictionForm(forms.Form):
 song_name=forms.CharField(initial="My New Song"); language=forms.ChoiceField(choices=[(x,x) for x in ["Hindi","English","Punjabi","Marathi","Tamil","Telugu","Bengali","Kannada","Malayalam","Gujarati"]]); genre=forms.ChoiceField(choices=[(x,x) for x in ["Pop","Romantic","Hip-Hop","Rock","Classical","Indie","Devotional","Electronic","Folk","Lo-Fi"]])
 current_streams=forms.FloatField(min_value=1,initial=150000); current_listeners=forms.FloatField(min_value=1,initial=100000); repeat_rate=forms.FloatField(min_value=0,max_value=1,initial=.30); skip_rate=forms.FloatField(min_value=0,max_value=1,initial=.20); completion_rate=forms.FloatField(min_value=0,max_value=1,initial=.70); save_rate=forms.FloatField(min_value=0,max_value=1,initial=.08); share_rate=forms.FloatField(min_value=0,max_value=1,initial=.03); playlist_add_rate=forms.FloatField(min_value=0,max_value=1,initial=.05); avg_stream_growth=forms.FloatField(initial=.15); max_stream_growth=forms.FloatField(initial=.30); growth_acceleration=forms.FloatField(initial=.05)
